import{_ as n,a0 as d,w as p,s as u,ao as a,I as r,x as e,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"如何在 Ubuntu 中录制流媒体音频 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中录制流媒体音频 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中录制流媒体音频 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中录制流媒体音频 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20220810 How to Record Streaming Audio in Ubuntu and other Linux Distributions","title":"如何在 Ubuntu 中录制流媒体音频","tag":"202212","desc":""},"relativePath":"202212/20220810 How to Record Streaming Audio in Ubuntu and other Linux Distributions.md","filePath":"[post].md"}'),l={name:"202212/20220810 How to Record Streaming Audio in Ubuntu and other Linux Distributions.md"};function g(h,t,b,m,f,k){const i=d("Link");return p(),u("div",null,[t[33]||(t[33]=a('<h1 id="如何在-ubuntu-中录制流媒体音频" tabindex="-1">如何在 Ubuntu 中录制流媒体音频 <a class="header-anchor" href="#如何在-ubuntu-中录制流媒体音频" aria-label="Permalink to “如何在 Ubuntu 中录制流媒体音频”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/25/154829ol11lp47i8o6222c.jpg" alt=""></p><blockquote><p>如何在 Ubuntu 和其他 Linux 发行版中录制音频？</p></blockquote><p>如果你想通过计算机的麦克风录制语音，可以使用 GNOME <ruby>录音机<rt>Sound Recorder</rt></ruby> 或 Audacity。</p><p>使用 GNOME 录音机很简单，但它功能不足。Audacity 最初可能会让人无从入手，但它有很多专业级录音的功能。不过，在本教程中，我不打算详细讨论这个问题。</p><p>GNOME 录音机能与麦克风配合使用。还有一个叫做 Audio recorder 的工具，除了麦克风输入，你可以使用它来录制流媒体音乐（来自 Sptify、YouTube、互联网广播、Skype 和其他大多数来源）。</p><p>总而言之，我将向你展示以下步骤：</p><ul><li>使用 GNOME 录音机录制声音</li><li>使用 Audio Recorder 录制流音频</li></ul><h3 id="使用-gnome-录音机从麦克风录制音频" tabindex="-1">使用 GNOME 录音机从麦克风录制音频 <a class="header-anchor" href="#使用-gnome-录音机从麦克风录制音频" aria-label="Permalink to “使用 GNOME 录音机从麦克风录制音频”">​</a></h3><p>GNOME 桌面环境有很多有用的应用程序，录音机就是其中之一。</p>',10)),r("p",null,[t[1]||(t[1]=e("你可以从 Ubuntu 软件中心安装 ",-1)),o(i,{href:"https://wiki.gnome.org/Apps/SoundRecorder"},{default:s(()=>[...t[0]||(t[0]=[e("录音机",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[34]||(t[34]=a('<p><img src="https://itsfoss.com/wp-content/uploads/2022/08/sound-recorder-ubuntu.png" alt="Sound Recorder can be installed from the Ubuntu Software Center"></p><p>或者，你可以在终端中使用此命令来安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gnome-sound-recorder</span></span></code></pre></div><p>安装后，你可以在系统菜单中找到它，并从那里启动它。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/sound-recorder.png" alt="GNOME Sound Recorder"></p><p>在开始使用它之前，应确保在系统设置中选择了正确的输入源：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/microphone-settings-ubuntu.png" alt="Ensure that you have chosen correct input in system settings"></p><p>打开录音机，它将显示如下界面：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/using-sound-recorder-linux.png" alt="Hit the Record button to start audio recording"></p><p>点击“<ruby>录制<rt>Record</rt></ruby>”按钮，它立即开始录制音频。录制时，你可以选择暂停、停止或取消录制。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/sound-recording-with-sound-recorder.png" alt="Options while recording audio"></p><p>你的录音将保存并可从应用程序界面本身获得。单击保存的录音以突出显示。</p><p>你可以回放或删除该录音。你可以通过单击“保存/下载”按钮选择将其保存到其他位置。你也可以使用“编辑”按钮重命名该录音。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/sound-recorder-interface.png" alt="Saved recordings"></p><p>这很方便，对吧？你可以选择以 <code>MP3</code>、<code>FLAC</code> 和多种格式录制。</p><h4 id="删除-gnome-录音机" tabindex="-1">删除 GNOME 录音机 <a class="header-anchor" href="#删除-gnome-录音机" aria-label="Permalink to “删除 GNOME 录音机”">​</a></h4><p>不喜欢它或发现它缺乏功能？</p><p>你可以从 Ubuntu 软件中心删除 GNOME 录音机，或使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove gnome-sound-recorder</span></span></code></pre></div><p>GNOME 录音机应用功能有限，它只从麦克风录制，在某些情况下这不是你想要的。</p><p>想象一下你想录制 Skype 通话或在应用程序或网络浏览器中播放的内容？在这种情况下，漂亮的 Audio Recorder 会有所帮助。</p><h3 id="使用-audio-recorder-来录制流媒体音频" tabindex="-1">使用 Audio Recorder 来录制流媒体音频 <a class="header-anchor" href="#使用-audio-recorder-来录制流媒体音频" aria-label="Permalink to “使用 Audio Recorder 来录制流媒体音频”">​</a></h3>',22)),r("p",null,[t[4]||(t[4]=e("你可以使用 ",-1)),o(i,{href:"https://launchpad.net/~audio-recorder/+archive/ubuntu/ppa"},{default:s(()=>[...t[3]||(t[3]=[e("官方 PPA",-1)])]),_:1}),t[5]||(t[5]=e(" 在 Ubuntu 和 LinuxMint 中安装 ",-1)),t[6]||(t[6]=r("code",null,"Audio Recorder",-1)),t[7]||(t[7]=e("。在终端中依次使用以下命令：",-1))]),t[35]||(t[35]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:audio-recorder/ppa</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install audio-recorder</span></span></code></pre></div>`,1)),r("p",null,[t[9]||(t[9]=e("或者，你可以从 ",-1)),o(i,{href:"https://launchpad.net/audio-recorder"},{default:s(()=>[...t[8]||(t[8]=[e("启动台",-1)])]),_:1}),t[10]||(t[10]=e(" 下载源代码。安装后，你可以从“",-1)),t[11]||(t[11]=r("ruby",null,[e("活动概述"),r("rt",null,"Activity Overview")],-1)),t[12]||(t[12]=e("”里启动应用程序：",-1))]),t[36]||(t[36]=a('<p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-in-overview.png" alt="Audio Recorder"></p><h4 id="记录不同来源的各种声音" tabindex="-1">记录不同来源的各种声音 <a class="header-anchor" href="#记录不同来源的各种声音" aria-label="Permalink to “记录不同来源的各种声音”">​</a></h4><p>Audio Recorder 记录计算机产生的各种声音。</p><p>它记录通过系统声卡、麦克风、浏览器、网络摄像头等播放的音频。</p><p>换句话说，即使你的系统打喷嚏，它也会记录（如果你想记录的话）。它允许你选择录制设备，如网络摄像头、麦克风、Skype 等。</p><p>要录制流媒体音乐，请选择适当的源。例如，如果你正在 Rhythmbox 中播放流媒体广播，请选择 Rythmbox。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-audio-settings.png" alt="Audio-Recorder Audio Settings"></p><h4 id="在你方便的时候录制" tabindex="-1">在你方便的时候录制 <a class="header-anchor" href="#在你方便的时候录制" aria-label="Permalink to “在你方便的时候录制”">​</a></h4><p>Audio Recorder 还提供了设置计时器的选项。你可以在给定的时钟时间或预定义的间隔开始、停止或暂停录制。你还可以设置录制文件大小的限制。</p><p>此外，你可以在没有音频（或声音很低）时暂停（和停止），并在声音恢复时继续。</p><p>你所要做的就是编辑计时器面板中的文本。注释掉你不想应用的“规则”，并根据你的要求编辑这些规则。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-timer-settings.png" alt="Audio-recorder Timer Settings"></p><p>它提供了其他设置，如登录时自动启动、显示托盘图标和其他记录设置。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-additional-settings.png" alt="Audio-recorder Additional Settings"></p><h4 id="以各种文件格式保存录制的音乐文件" tabindex="-1">以各种文件格式保存录制的音乐文件 <a class="header-anchor" href="#以各种文件格式保存录制的音乐文件" aria-label="Permalink to “以各种文件格式保存录制的音乐文件”">​</a></h4><p>另一个宝藏。你可以将录制的文件保存为你喜爱的文件格式。支持的文件格式有 OGG 音频、Flac、MP3、SPX 和 WAV。我录音时更喜欢用 MP3 格式。</p><p>录制的文件存储在 <code>~/Audio</code> 中，即主目录中的“音频”文件夹中。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/audio-recorder-audio-formats.png" alt="Audio-recorder Audio Formats"></p><h4 id="audio-recorder-有多好" tabindex="-1">Audio Recorder 有多好？ <a class="header-anchor" href="#audio-recorder-有多好" aria-label="Permalink to “Audio Recorder 有多好？”">​</a></h4>',19)),r("p",null,[t[14]||(t[14]=e("我在 Ubuntu 中使用 Audio Recorder ",-1)),o(i,{href:"https://itsfoss.com/youtube-dl-audio-only/"},{default:s(()=>[...t[13]||(t[13]=[e("录制 YouTube 上播放的音乐",-1)])]),_:1}),t[15]||(t[15]=e("。我用 MP3 格式保存了一段 2 分钟的视频，占用了 934 KB 的空间。但我必须说，我没想到录制的音质会这么好。老实说，我无法将它与 YouTube 上的原始歌曲区分开来。",-1))]),t[37]||(t[37]=a('<h4 id="删除-audio-recorder" tabindex="-1">删除 Audio Recorder <a class="header-anchor" href="#删除-audio-recorder" aria-label="Permalink to “删除 Audio Recorder”">​</a></h4><p>如果你不喜欢 Audio Recorder，可以使用以下命令将其删除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove audio-recorder</span></span></code></pre></div>',3)),r("p",null,[o(i,{href:"https://itsfoss.com/how-to-remove-or-delete-ppas-quick-tip/"},{default:s(()=>[...t[16]||(t[16]=[e("同时删除 PPA",-1)])]),_:1}),t[17]||(t[17]=e(" 是个好主意：",-1))]),t[38]||(t[38]=a('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository -r ppa:audio-recorder/ppa</span></span></code></pre></div><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>Linux 中可能还有其他几种用于音频录制的工具。像 GNOME 一样，其他桌面环境也可能有录音应用程序。我知道深度操作系统肯定有一个。</p><p>GNOME 录音机是一个不错的工具，用于从麦克风录制声音。对于录制各种来源的声音，Audio Recorder 是一个不错的选择。</p><p>我希望这篇文章能满足你的录音需求。如果你有什么建议，请告诉我。</p><hr>',6)),r("p",null,[t[19]||(t[19]=e("via: ",-1)),o(i,{href:"https://itsfoss.com/record-streaming-audio/"},{default:s(()=>[...t[18]||(t[18]=[e("https://itsfoss.com/record-streaming-audio/",-1)])]),_:1})]),r("p",null,[t[24]||(t[24]=e("作者：",-1)),o(i,{href:"https://itsfoss.com/"},{default:s(()=>[...t[20]||(t[20]=[e("Abhishek Prakash",-1)])]),_:1}),t[25]||(t[25]=e(" 选题：",-1)),o(i,{href:"https://github.com/lkxed"},{default:s(()=>[...t[21]||(t[21]=[e("lkxed",-1)])]),_:1}),t[26]||(t[26]=e(" 译者：",-1)),o(i,{href:"https://github.com/FYJNEVERFOLLOWS"},{default:s(()=>[...t[22]||(t[22]=[e("FYJNEVERFOLLOWS",-1)])]),_:1}),t[27]||(t[27]=e(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[23]||(t[23]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[30]||(t[30]=e("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[28]||(t[28]=[e("LCTT",-1)])]),_:1}),t[31]||(t[31]=e(" 原创编译，",-1)),o(i,{href:"https://linux.cn/"},{default:s(()=>[...t[29]||(t[29]=[e("Linux中国",-1)])]),_:1}),t[32]||(t[32]=e(" 荣誉推出",-1))])])}const x=n(l,[["render",g]]);export{A as __pageData,x as default};
